Game.prototype.fixColors=function(){
  this.scene.traverse(o=>{
    if(!o.material)return;
    const ms=Array.isArray(o.material)?o.material:[o.material];
    ms.forEach(m=>{
      if(!m.userData)m.userData={};
      if(m.userData._lin)return;
      if(m.color)m.color.convertSRGBToLinear();
      if(m.emissive)m.emissive.convertSRGBToLinear();
      m.userData._lin=true;
    });
  });
  if(this.water){const u=this.water.material.uniforms;
    u.deep.value.convertSRGBToLinear();u.shallow.value.convertSRGBToLinear();u.sun.value.convertSRGBToLinear();}
};

